import { useCallback, useEffect, useMemo, useState } from 'react'
import { useHistory } from 'react-router-dom'
import { useParams } from 'react-router'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Container } from '../../../../../../components'
import ProductBottomSheet from '../../../../../../components/ProductBottomSheet'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { PAYMENT_GATEWAY } from '../../../../../../constants/payment'
import { LANG_STRINGS } from '../../../../../../lang/index'
import {
  LINK_ICON,
  HOME_ICON,
  SHIELD_ICON,
} from '../../../../../../images/imageUrl'
import {
  useGetPaymentStatusReq,
  useGetPolicyDetails,
} from '../../../state/hooks/usePaymentState'
import {
  copySharingData,
  getQueryParams,
} from '../../../../../../helpers/utility'
import ContentSuccess from '../components/ContentSuccess'
import ContentFailed from '../components/ContentFailed'
import ContentInProgress from '../components/ContentInProgress'
import { PaymentSuccessStyle } from './index.style'
import { getQsLink } from './helpers'

const PAYMENT_STATE = {
  IN_PROGRESS: 'IN_PROGRESS',
  SUCCESS: 'SUCCESS',
  FAILED: 'FAILED',
}

const ACTIONS = [
  {
    icon: LINK_ICON,
    type: 'copy-link',
    label: LANG_STRINGS.copyQsLink,
  },
  {
    icon: SHIELD_ICON,
    type: 'new-protection',
    label: LANG_STRINGS.makeNewProtection,
  },
  {
    icon: HOME_ICON,
    type: 'home',
    label: LANG_STRINGS.backToHomeSentence,
  },
]

function PaymentSuccessContainer() {
  const history = useHistory()
  const { policyId, transactionId } = useParams()
  const source = useMemo(() => getQueryParams('source') || PAYMENT_GATEWAY, [])

  const [paymentState, setPaymentState] = useState(PAYMENT_STATE.IN_PROGRESS)
  const [showProductModal, setShowProductModal] = useState()

  const [{ getPolicyDetailData = {} }, getPolicyDetailsReq] =
    useGetPolicyDetails()
  const [{ getPaymentStatusData = {} }, getPaymentStatusReq] =
    useGetPaymentStatusReq()
  const [{ GET_POLICY_DETAIL_LOADER, GET_PAYMENT_STATUS_LOADER }] =
    useLoaderContextValue()

  useEffect(() => {
    getPolicyDetailsReq({
      policyId: policyId,
    })
    getPaymentStatusReq({
      transactionId: transactionId,
      query: { source: source },
    })
  }, [
    policyId,
    transactionId,
    source,
    getPolicyDetailsReq,
    getPaymentStatusReq,
  ])

  useEffect(() => {
    const policyStatus = getPolicyDetailData.status
    const policyPaymentStatus = getPolicyDetailData.payment_status
    const paymentStatus = getPaymentStatusData.payment_status

    switch (true) {
      case paymentStatus === 'ACTIVE':
      case [policyPaymentStatus, policyStatus].includes('PAYMENT_PENDING'):
        setPaymentState(PAYMENT_STATE.IN_PROGRESS)
        break
      case paymentStatus === 'COMPLETED':
        setPaymentState(PAYMENT_STATE.SUCCESS)
        break
      case paymentStatus === 'EXPIRED':
      default:
        setPaymentState(PAYMENT_STATE.FAILED)
        break
    }
  }, [getPolicyDetailData, getPaymentStatusData])

  const handleNavigateToTransactionPage = useCallback(() => {
    history.push(`/transactions/${policyId}/details`)
  }, [history, policyId])

  const handleActionClick = useCallback(
    (actionType) => {
      switch (actionType) {
        case 'copy-link':
          const qsLink = getQsLink(getPolicyDetailData)
          copySharingData(qsLink)
          ShowSnackbar.success({ text: 'Menyalin ke clipboard berhasil' })
          break
        case 'new-protection':
          setShowProductModal(true)
          break
        case 'home':
          history.push('/dashboard')
          break
        default:
          break
      }
    },
    [history, getPolicyDetailData]
  )

  return (
    <Container
      loader={GET_POLICY_DETAIL_LOADER || GET_PAYMENT_STATUS_LOADER}
      mitraHeader
      hideBottomTabs
      hideGuardianInfo
      hideBackButton
      closeIcon
      onClose={() => history.push('/dashboard')}
    >
      {getPolicyDetailData?.id && (
        <PaymentSuccessStyle>
          {paymentState === PAYMENT_STATE.IN_PROGRESS && (
            <ContentInProgress
              policyDetail={getPolicyDetailData}
              onNavigateToTransactionPage={handleNavigateToTransactionPage}
            />
          )}
          {paymentState === PAYMENT_STATE.SUCCESS && (
            <ContentSuccess
              policyDetail={getPolicyDetailData}
              onNavigateToTransactionPage={handleNavigateToTransactionPage}
            />
          )}
          {paymentState === PAYMENT_STATE.FAILED && (
            <ContentFailed
              policyDetail={getPolicyDetailData}
              onNavigateToTransactionPage={handleNavigateToTransactionPage}
            />
          )}
          <div className="actions-container">
            {ACTIONS.map((action, i) => (
              <div key={i} onClick={() => handleActionClick(action.type)}>
                <img src={action.icon} alt="" />
                <div>{action.label}</div>
              </div>
            ))}
          </div>
        </PaymentSuccessStyle>
      )}
      {showProductModal && (
        <ProductBottomSheet
          show={showProductModal}
          onClose={() => setShowProductModal(false)}
        />
      )}
    </Container>
  )
}

export default PaymentSuccessContainer
