import { InputStyle } from './index.style'
import { LANG_STRINGS } from '../../../../lang/index'
import FormItemLabel from '../FormItemLabel'
import { Error } from '../../../../commonStyle/index.style'
import { MINI_INFO } from '../../../../images'
import { CustomText } from '../../..'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { useEffect } from 'react'

function Input ({
  placeholder, backgroundColor, error, subText,
  className, name, displayBorder, defaultValue,
  opacity, value, title, maxlength, required, type, ...props
}) {
  useEffect(() => {
    const el = document.getElementById(name)
    if (el) {
      el.addEventListener('focusin', (e) => {
        e.preventDefault()
        e.stopPropagation()
      })
    }
  }, [name])

  return (
    <InputStyle
      error={error}
      backgroundColor={backgroundColor}
      displayBorder={displayBorder}
      opacity={opacity}
      id={name}
    >
      {
        title && (
          <FormItemLabel
            title={title}
            required={required}
          />
        )
      }
      {
        type === 'textarea' ? (
          <textarea
            value={value}
            defaultValue={defaultValue}
            placeholder={placeholder || LANG_STRINGS.enterSomething}
            {...props}
            className={`${className} input-style`}
            maxLength={maxlength}
            autoComplete={props.autocomplete || "chrome-off"}
            data-form-type="other"
            data-lpignore="true"
          />
        ) : (
          <input
            placeholder={placeholder || LANG_STRINGS.enterSomething}
            defaultValue={defaultValue || value}
            {...props}
            className={`${className || ''} input-style`}
            maxLength={maxlength}
            autoComplete={props.autocomplete || "chrome-off"}
            data-form-type="other"
            data-lpignore="true"
          />
        )
      }
      {
        subText && (
          <CustomText
            color={AgentColorPallette.fontGrey}
            size='0.7em'
            top='0.4rem'
            className='display-flex flex-start'
          >
            <img src={MINI_INFO} alt='Info' />&nbsp;&nbsp;<span>{subText}</span>
          </CustomText>
        )
      }
      <Error>{error}</Error>
    </InputStyle>
  )
}

export default Input
