import { usePaymentContextValue } from '../../context'
import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import {
  getPolicyDetails,
  agentPayingReq,
  customerPayingRequest,
  customerPayingTravelRequest,
  generatePaymentUrlReq,
  getVaPaymentDetailsRequest,
  getPaymentStatus,
} from '../actions'

export const usePaymentServiceCall = (actionsCall = () => {}) => {
  const [policyState, dispatch] = usePaymentContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(
    async (payload = {}) => {
      await callApi(
        actionsCall({
          ...payload,
        })
      )
    },
    [callApi, actionsCall]
  )

  return [policyState, request]
}

export const useGetPolicyDetails = () => usePaymentServiceCall(getPolicyDetails)

export const useCustomerPaying = () =>
  usePaymentServiceCall(customerPayingRequest)

export const useCustomerTravelPaying = () =>
  usePaymentServiceCall(customerPayingTravelRequest)

export const useGeneratePaymentUrl = () =>
  usePaymentServiceCall(generatePaymentUrlReq)

export const useVAPaymentDetails = () =>
  usePaymentServiceCall(getVaPaymentDetailsRequest)

export const useAgentPaying = () => usePaymentServiceCall(agentPayingReq)

export const useGetPaymentStatusReq = () =>
  usePaymentServiceCall(getPaymentStatus)
