import { PAYMENT_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case PAYMENT_ACTIONS.GET_POLICY_DETAIL:
    case PAYMENT_ACTIONS.CUSTOMER_PAYING:
    case PAYMENT_ACTIONS.GET_PAYMENT_URL:
    case PAYMENT_ACTIONS.GET_VA_DETAIL:
    case PAYMENT_ACTIONS.AGENT_PAYING:
    case PAYMENT_ACTIONS.GET_PAYMENT_STATUS:
      return {
        ...state,
        ...payload,
      }
    default:
      return { ...state }
  }
}

export default reducer
